import json
with open('/app/resources/treasury_bulletin_2007_09.json', 'r') as f:
    data = json.load(f)

# Find all elements that contain 'employment' or '2004' in any text field
def search_elements(obj, path=''):
    results = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            new_path = f'{path}.{k}' if path else k
            results.extend(search_elements(v, new_path))
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            results.extend(search_elements(item, f'{path}[{i}]'))
    elif isinstance(obj, str):
        if 'employment' in obj.lower() or '2004' in obj or '2005' in obj or '2006' in obj:
            results.append((path, obj[:300]))
    return results

results = search_elements(data)
for path, text in results[:30]:
    print(f'{path}:')
    print(text)
    print('---')
